#!/usr/bin/env python3
"""
CutSync — AI Music Generation Studio: Project Unpacker
Run this script to automatically unpack the complete project repository.
"""
import base64
import os
import zipfile

ZIP_B64 = ""

def main():
    zip_bytes = base64.b64decode(ZIP_B64)
    zip_filename = "cutsync-ai-music-studio.zip"
    with open(zip_filename, "wb") as f:
        f.write(zip_bytes)
    print(f"[CutSync] Saved {zip_filename} ({len(zip_bytes)} bytes)")
    
    extract_dir = "cutsync-ai-music-studio"
    os.makedirs(extract_dir, exist_ok=True)
    with zipfile.ZipFile(zip_filename, "r") as z:
        z.extractall(extract_dir)
    print(f"[CutSync] Extracted all files into '{extract_dir}/'")
    print("Ready for GitHub upload!")

if __name__ == '__main__':
    main()
